mapper.select:
SELECT C.ShipCheckNo, C.ShopCode, S.ShopName AS ShopName, C.ShipCheckDesc, CAST(C.ShipCheckDate AS CHAR) AS ShipCheckDate, C.OrderCount, C.PrintCount, C.State, C.Remark, C.RegistId, C.RegistName, CAST(C.RegistDate AS CHAR) AS RegistDate, C.ChangeId, C.ChangeName, CAST(C.ChangeDate AS CHAR) AS ChangeDate FROM shopwizard.tShpShipCheck C LEFT OUTER JOIN shopwizard.tCmpShop S ON S.ShopCode = C.ShopCode
ORDER BY C.ShipCheckNo DESC
LIMIT ${pPageOffset}, ${pPageSize}

mapper.insert:
INSERT INTO shopwizard.tShpShipCheck (
    ShopCode, ShipCheckDesc, ShipCheckDate, OrderCount, PrintCount, State, Remark, RegistId, RegistName, RegistDate, ChangeId, ChangeName, ChangeDate
) VALUES (
    #{shopCode}, #{shipCheckDesc}, #{shipCheckDate}, #{orderCount}, #{printCount}, #{state}, #{remark}, #{registId}, #{registName}, #{registDate}, #{changeId}, #{changeName}, #{changeDate}
)

mapper.update:
UPDATE shopwizard.tShpShipCheck SET
    PrintCount = IFNULL(PrintCount, 0) + 1, ChangeId = #{changeId}, ChangeName = #{changeName}, ChangeDate = NOW()
WHERE ShipCheckNo = #{shipCheckNo}
